//! # Legacy packet-id translation
//!
//! Maps a raw packet ID between a client's protocol version and Steel's native version.
//! The matrices are generated by `steel-registry` from extracted `packets.json` files —
//! one per supported protocol — and are aligned by each packet's registry path, so no id
//! is transcribed by hand.
//!
//! Orientation of a generated row, per direction:
//! - **clientbound** (server→client): `REMAP[column][current_id] = client_id`.
//! - **serverbound** (client→server): `REMAP[column][client_id] = current_id`.
//!
//! A row value of [`ABSENT`] means the version has no such packet, and a `from_id` past
//! the end of the row means the id was never assigned. Both translate to `None`, i.e. the
//! packet is dropped rather than delivered with an id the client cannot interpret.
//!
//! Only the id is rewritten here. Payloads whose *layout* differs between versions are
//! handled by the structural adapters, which run around this step.

use crate::utils::ConnectionProtocol;
use crate::version::MinecraftVersion;
use steel_registry::packets::legacy::{
    ABSENT, CLIENTBOUND_REMAPS, PHASE_CONFIG, PHASE_HANDSHAKE, PHASE_LOGIN, PHASE_PLAY,
    PHASE_STATUS, REMAP_WIDTH, SERVERBOUND_REMAPS, column_of,
};

/// The matrix column for a client version, or `None` when no extracted table covers it.
///
/// A version without a table was never extracted by `SteelExtractor`, so it must not be
/// served translated ids it was not measured against.
#[must_use]
pub const fn column_for(version: MinecraftVersion) -> Option<usize> {
    column_of(version.protocol())
}

/// Index of the native version's column (always the last one).
#[must_use]
pub const fn current_column() -> usize {
    REMAP_WIDTH - 1
}

/// The version this connection must translate to, or `None` when no translation is needed.
///
/// `None` covers both the native client and a version whose packet table was never
/// extracted. The handshake admits a client only when this returns `Some` (or the client is
/// native), so a connection in play state always has a usable matrix column here.
#[must_use]
pub const fn translation_for(version: MinecraftVersion) -> Option<MinecraftVersion> {
    if version.is_current() {
        return None;
    }
    match column_of(version.protocol()) {
        Some(_) => Some(version),
        None => None,
    }
}

/// The phase slot of a connection protocol within the generated tables.
const fn phase_index(phase: ConnectionProtocol) -> usize {
    match phase {
        ConnectionProtocol::Handshake => PHASE_HANDSHAKE,
        ConnectionProtocol::Status => PHASE_STATUS,
        ConnectionProtocol::Login => PHASE_LOGIN,
        ConnectionProtocol::Config => PHASE_CONFIG,
        ConnectionProtocol::Play => PHASE_PLAY,
    }
}

/// Translates a server→client id from the native version to `column`'s numbering.
///
/// Returns `None` when `column`'s version has no such packet, meaning the packet must be
/// dropped instead of sent.
#[must_use]
pub fn remap_clientbound(column: usize, phase: ConnectionProtocol, current_id: i32) -> Option<i32> {
    CLIENTBOUND_REMAPS
        .get(phase_index(phase))?
        .get(column)
        .and_then(|row| lookup(row, current_id))
}

/// Translates a client→server id from `column`'s numbering to the native version.
///
/// Returns `None` when the id is unknown to that version, meaning it must not be
/// dispatched to a handler expecting different bytes.
#[must_use]
pub fn remap_serverbound(column: usize, phase: ConnectionProtocol, client_id: i32) -> Option<i32> {
    SERVERBOUND_REMAPS
        .get(phase_index(phase))?
        .get(column)
        .and_then(|row| lookup(row, client_id))
}

/// Reads `from_id` out of one generated row, rejecting absent and unassigned ids.
fn lookup(row: &[i16], from_id: i32) -> Option<i32> {
    let index = usize::try_from(from_id).ok()?;
    let translated = *row.get(index)?;
    (translated != ABSENT).then_some(i32::from(translated))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn native_column_is_the_identity_over_every_assigned_id() {
        let column = current_column();
        let phases = [
            ConnectionProtocol::Handshake,
            ConnectionProtocol::Status,
            ConnectionProtocol::Login,
            ConnectionProtocol::Config,
            ConnectionProtocol::Play,
        ];

        let mut checked = 0usize;
        for phase in phases {
            let index = phase_index(phase);
            for (remap, remaps) in [
                ("clientbound", CLIENTBOUND_REMAPS),
                ("serverbound", SERVERBOUND_REMAPS),
            ] {
                // A direction without this phase has an empty slot (no clientbound
                // handshake, no serverbound packets the client never sends).
                let Some(row) = remaps[index].get(column) else {
                    assert!(
                        remaps[index].is_empty(),
                        "{remap} {phase:?} has columns but no native column"
                    );
                    continue;
                };
                for (id, &mapped) in row.iter().enumerate() {
                    let id = id as i32;
                    let expected = (mapped != ABSENT).then_some(i32::from(mapped));
                    let translated = if remap == "clientbound" {
                        remap_clientbound(column, phase, id)
                    } else {
                        remap_serverbound(column, phase, id)
                    };
                    assert_eq!(
                        translated, expected,
                        "{remap} {phase:?} id {id} must round-trip on the native version"
                    );
                    assert_eq!(
                        translated,
                        Some(id),
                        "{remap} {phase:?} id {id} must map to itself natively"
                    );
                    checked += 1;
                }
                // An id one past the end was never assigned and must be dropped.
                let beyond = row.len() as i32;
                let dropped = if remap == "clientbound" {
                    remap_clientbound(column, phase, beyond)
                } else {
                    remap_serverbound(column, phase, beyond)
                };
                assert_eq!(
                    dropped, None,
                    "{remap} {phase:?} id {beyond} must be dropped"
                );
            }
        }

        assert!(
            checked > 200,
            "the identity check must cover the real packet tables, saw {checked} ids"
        );
    }

    #[test]
    fn ids_beyond_the_table_are_rejected() {
        let column = current_column();
        // The largest generated phase is play clientbound; ids past every row's end have no
        // packet, and must be dropped rather than delivered.
        assert_eq!(
            remap_clientbound(column, ConnectionProtocol::Play, 100_000),
            None
        );
        assert_eq!(
            remap_serverbound(column, ConnectionProtocol::Play, 100_000),
            None
        );
    }

    #[test]
    fn negative_ids_are_rejected() {
        let column = current_column();
        assert_eq!(
            remap_clientbound(column, ConnectionProtocol::Play, -1),
            None
        );
        assert_eq!(
            remap_serverbound(column, ConnectionProtocol::Play, -5),
            None
        );
    }

    #[test]
    fn unknown_columns_have_no_mapping() {
        assert_eq!(remap_clientbound(9_999, ConnectionProtocol::Play, 0), None);
        assert_eq!(remap_serverbound(9_999, ConnectionProtocol::Play, 0), None);
    }

    #[test]
    fn native_version_resolves_to_the_last_column() {
        assert_eq!(
            column_for(MinecraftVersion::CURRENT),
            Some(current_column()),
            "the native version must always have a table"
        );
    }

    #[test]
    fn unextracted_versions_have_no_column() {
        for &version in MinecraftVersion::ALL {
            if version.is_current() {
                continue;
            }
            // No `packets-<protocol>.json` has been extracted yet, so no legacy version may
            // resolve a column. Landing an extraction for a version must update this test to
            // expect a column, which is what makes the gate observable.
            assert_eq!(
                column_for(version),
                None,
                "{version} has no extracted packet table and must not be served ids"
            );
        }
    }
}
